import java.util.*;
import java.io.*;
import java.math.*;

public class E {
    private static final BigInteger MOD = BigInteger.valueOf(998244353L);

    public static void main(String[] args) throws Exception {
        BufferedReader infile = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(infile.readLine());

        long[] nums = new long[4];
        for (int i = 0; i < 4; i++) {
            nums[i] = Long.parseLong(st.nextToken());
        }

        long N = nums[0];
        long M = nums[1];
        long L = nums[2];
        long R = nums[3];

        long cells = N * M;
        BigInteger base = BigInteger.valueOf(R - L + 1);
        BigInteger bigResult = powMod(base, cells, MOD);
        long result = bigResult.longValue();

        if ((cells % 2L) == 1L) {
            System.out.println(result);
        } else {
            if (((R - L) % 2L) == 0L) {
                result++;
            }
            result = (result * ((MOD.longValue() + 1) / 2L)) % MOD.longValue();
            System.out.println(result);
        }
    }

    private static BigInteger powMod(BigInteger base, long exponent, BigInteger mod) {
        if (base.signum() < 0 || exponent < 0) {
            return base.modPow(BigInteger.valueOf(exponent), mod);
        }

        BigInteger result = BigInteger.ONE;
        BigInteger factor = base.mod(mod);

        while (exponent > 0) {
            if ((exponent & 1L) != 0L) {
                result = result.multiply(factor).mod(mod);
            }
            exponent >>>= 1;
            factor = factor.multiply(factor).mod(mod);
        }

        return result;
    }
}
